          credentialHandles: [{ id: "writer", headerNames: ["authorization"] }],
          resolveCredentials: () => ({ authorization: `Bearer ${token}` }),
        },
      },
    );
    async function exchange(
      method: "GET" | "HEAD" | "POST",
      suffix: string,
      status: number,
      headers: Record<string, string> = {},
      input?: unknown,
      schemaName?: string,
    ) {
