    expect(page.after).toMatch(/^cg_[A-Za-z0-9_-]{43}_[A-Za-z0-9_-]{43}_1$/);
    expect(eligible.response.headers["content-length"]).toBe(String(eligible.response.bodyOctets));
    const opaque = {
      ...minimum,
      "bdp-minimum-scope-position": "unknown",
