      if (cleanClose && pendingDrained && assertionsCompleted && failures.length === 0) {
        if (!existsSync(directory) || realpathSync(directory) !== ownedDirectory) {
          fail(
            "directory-ownership",
            new Error("installed opaque changefeed directory ownership changed"),
          );
