1	/** Bounded observation of a deliberately nonterminal raw HTTP/1.1 stream.
2	 * Separate from the finite exact executor: closing is not a completed response. */
3	import { connect } from "node:net";
4	export function recordRawSse(options: {
5	  dial: string;
6	  host: string;
7	  target: string;
8	  headers: readonly [string, string][];
9	  method?: "GET" | "HEAD";
10	  signal: AbortSignal;
11	  timeoutMs?: number;
12	}) {
13	  const started = performance.now();
14	  const ready = Promise.withResolvers<void>();
15	  const closed = Promise.withResolvers<void>();
16	  void ready.promise.catch(() => {});
17	  const address = new URL(options.dial);
18	  const socket = connect({ host: address.hostname, port: Number(address.port) });
19	  const chunks: Buffer[] = [];
20	  let total = 0,
21	    status = 0,
22	    headers: Record<string, string> = {},
23	    body = "",
24	    failure: unknown;
25	  const subscribers = new Set<() => void>();
26	  const abort = () =>
27	    socket.destroy(
28	      options.signal.reason instanceof Error
29	        ? options.signal.reason
30	        : new Error("SSE observation aborted"),
31	    );
