1	/** Private finite whole-group replication. No Snapshot, SSE, pruning or mutable view. */
2	import { createHash } from "node:crypto";
3	import { constants } from "node:buffer";
4	import { parseCanonicalScope } from "@bdp/protocol";
5	import {
6	  TRANSACTION_RUNTIME_LIMITS,
7	  type TransactionEvent,
8	  type TransactionStateChange,
9	} from "./transaction-batch.js";
10	import {
11	  TRANSACTION_EVENT_GROUP_BYTES,
12	  projectTransactionEventGroup,
13	} from "./transaction-events.js";
14	import { TransactionMinimumFailure } from "./transaction-consistency.js";
15	import type { TransactionReadContext } from "./transaction-store.js";
16	
17	// Conservative additions even where stored source/id bytes already pay part.
18	// JSON UTF-8 bytes upper-bound UTF-16 code units; this is not a live heap bound.
19	export const TRANSACTION_CHANGEFEED_BYTES =
20	  TRANSACTION_EVENT_GROUP_BYTES +
21	  TRANSACTION_RUNTIME_LIMITS.inducedEvents *
22	    (TRANSACTION_RUNTIME_LIMITS.scopeSourceBytes + 258 + 32) +
23	  2 * TRANSACTION_RUNTIME_LIMITS.scopeSourceBytes +
24	  12 * 258 +
25	  4096;
26	if (TRANSACTION_CHANGEFEED_BYTES >= constants.MAX_STRING_LENGTH)
27	  throw new Error("transaction tuple cannot support whole-group serialization");
28	
29	export class TransactionChangefeedParameterError extends Error {
30	  constructor(
31	    message?: string,
32	    readonly context?: TransactionReadContext,
33	  ) {
34	    super(message);
35	  }
36	}
37	export type TransactionChangefeedIntent = { readonly after: string } | { readonly start: "now" };
38	interface TransactionVisibleChangeGroup {
39	  readonly scopeEpoch: string;
40	  readonly authorizationView: string;
41	  readonly checkpoint: string;
42	  readonly position: string;
43	  readonly previousPosition: string;
44	  readonly projectionAdvance: false;
45	  readonly transaction: string;
46	  readonly changes: readonly TransactionStateChange[];
47	  readonly erasures: readonly never[];
48	  readonly eventCount: number;
49	  readonly events: readonly TransactionEvent[];
50	}
51	export type TransactionChangeGroup =
52	  | TransactionVisibleChangeGroup
53	  | {
54	      readonly scopeEpoch: string;
